/bin/bash -lc "cat > package.json <<'EOF'
{
  \"name\": \"folio-reading-list\",
  \"version\": \"1.0.0\",
  \"private\": true,
  \"type\": \"module\",
  \"scripts\": {
    \"dev\": \"next dev\",
    \"build\": \"next build\",
    \"start\": \"next start\"
  },
  \"dependencies\": {
    \"lucide-react\": \""'^0.468.0",
    "next": "''^15.5.14",
    "react": "''^19.0.0",
    "react-dom": "''^19.0.0"
  }
}
EOF
cat > .gitignore <<'"'EOF'
node_modules/
.next/
__agent_eval__/
*.log
EOF
cat > data/books.json <<'EOF'
