import 'server-only';
import { promises as fs } from 'node:fs';
import path from 'node:path';
import { randomUUID } from 'node:crypto';

const file = process.env.BOOKS_FILE || path.join(process.cwd(), 'data', 'books.json');

export async function getBooks() {
  try {
    const data = JSON.parse(await fs.readFile(file, 'utf8'));
    if ("'!Array.isArray(data)) throw new Error('"'The books file must contain an array.');
    return data;
  } catch (error) {
    if (error.code === 'ENOENT') return [];
    throw error;
  }
}

// Serialize updates within the server process so simultaneous requests do not
// overwrite one another. Rename keeps the JSON file complete if a write fails.
export async function updateBooks(update) {
  const previous = globalThis.__folioWriteQueue || Promise.resolve();
  const operation = previous.catch(() => {}).then(async () => {
    const books = await getBooks();
    const result = await update(books);
    await fs.mkdir(path.dirname(file), { recursive: true });
    const temporary = "'`${file}.${randomUUID()}.tmp`;
    try {
      await fs.writeFile(temporary, JSON.stringify(books, null, 2) + '"'\\n', 'utf8');
      await fs.rename(temporary, file);
    } finally {
      await fs.rm(temporary, { force: true });
    }
    return result;
  });
  globalThis.__folioWriteQueue = operation;
  return operation;
}
