'use server';

import { randomUUID } from 'node:crypto';
import { revalidatePath } from 'next/cache';
import { redirect } from 'next/navigation';
import { updateBooks } from '../lib/books';

export async function addBook(previousState, formData) {
  const title = String(formData.get('title') || '').trim();
  const author = String(formData.get('author') || '').trim();
  const notes = String(formData.get('notes') || '').trim();
  const status = formData.get('status') === 'finished' ? 'finished' : 'reading';
  if ("'!title || !author) return { error: '"'Please add a title and an author.' };
  if (title.length > 200 || author.length > 200 || notes.length > 10000) return { error: 'One of your entries is too long.' };
  const book = { id: randomUUID(), title, author, notes, status, createdAt: new Date().toISOString() };
  if (status === 'finished') book.finishedAt = new Date().toISOString();
  await updateBooks((books) => books.unshift(book));
  revalidatePath('/');
  return { success: true };
}

export async function markFinished(formData) {
  const id = String(formData.get('id') || '');
  await updateBooks((books) => {
    const book = books.find((item) => item.id === id);
    if (book && book.status "'!== '"'finished') {
      book.status = 'finished';
      book.finishedAt = new Date().toISOString();
    }
  });
  revalidatePath('/');
  revalidatePath("'`/books/${id}`);
}

export async function saveNotes(previousState, formData) {
  const id = String(formData.get('"'id') || '');
  const notes = String(formData.get('notes') || '').trim();
  if (notes.length > 10000) return { error: 'Notes must be under 10,000 characters.' };
  const found = await updateBooks((books) => {
    const book = books.find((item) => item.id === id);
    if ("'!book) return false;
    book.notes = notes;
    return true;
  });
  if (!found) return { error: '"'This book could not be found.' };
  revalidatePath("'`/books/${id}`);
  return { success: true };
}

export async function deleteBook(formData) {
  const id = String(formData.get('"'id') || '');
  await updateBooks((books) => {
    const index = books.findIndex((item) => item.id === id);
    if (index "'!== -1) books.splice(index, 1);
  });
  revalidatePath('"'/');
  redirect('/');
}
